import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestJuntarELimpar(unittest.TestCase):
    def test_juntar_devolve_as_duas_listas(self):
        """juntar devolve os itens das duas listas em uma so"""
        self.assertEqual(rodar()["juntar"]([1, 2], [3, 4]), [1, 2, 3, 4])

    def test_juntar_muda_a_primeira_lista(self):
        """juntar coloca os itens novos na primeira lista"""
        numeros = [1, 2]
        rodar()["juntar"](numeros, [3])
        self.assertEqual(numeros, [1, 2, 3])

    def test_esvaziar_devolve_lista_vazia(self):
        """esvaziar devolve uma lista vazia"""
        self.assertEqual(rodar()["esvaziar"]([5, 9]), [])

    def test_esvaziar_muda_a_lista(self):
        """esvaziar tira todos os itens da lista original"""
        numeros = [5, 9]
        rodar()["esvaziar"](numeros)
        self.assertEqual(numeros, [])

